WITH expected AS (SELECT row_number() OVER (ORDER BY a) AS pos,a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a LIMIT 10), got AS (SELECT result.*,row_number() OVER (PARTITION BY run ORDER BY result.rowid) AS pos FROM result) SELECT count(*) AS stored_rows,(SELECT count(*) FROM (SELECT run FROM result GROUP BY run HAVING run BETWEEN 1 AND 10 AND count(*)=10)) AS complete_runs,coalesce(sum((got.run NOT BETWEEN 1 AND 10) OR expected.pos IS NULL OR got.a IS NOT expected.a OR got.c1 IS NOT expected.c1 OR got.b IS NOT expected.b),0) AS bad_rows FROM got LEFT JOIN expected ON expected.pos=got.pos;